var counter int

func main() {
	var wg sync.WaitGroup
	for w := 0; w < 8; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < 125000; i++ {
				counter++
			}
		}()
	}
	wg.Wait()
	fmt.Println(counter)
}

