use std::thread;

fn main() {
	let mut counter = 0;
	let mut handles = Vec::new();
	for _ in 0..8 {
		handles.push(thread::spawn(|| {
			counter += 1;
		}));
	}
	for h in handles {
		h.join().unwrap();
	}
	println!("{counter}");
}

